/**
 * tools/bundle_gas.js — joins every production file into one Code.gs so the
 * Apps Script editor needs a single paste instead of 16 files.
 * Order matters: core_config first (every file reads CFG at load), core_messages before
 * core_sync (it merges SYNC_MSG into MSG at load), gas_sync before gas_main (doPost calls
 * gasSyncHandle and gasSyncTelegramDocument on every request). core_orders (custom tailoring)
 * only declares functions; it follows core_sync.
 *
 *   node tools/bundle_gas.js        ->  apps-script/dist/Code.gs and apps-script/dist/appsscript.json
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const FILES = [
  'core_config.js', 'core_burmese.js', 'core_messages.js', 'core_ai_prompt.js', 'core_ledger.js', 'core_report.js', 'core_bot.js', 'core_sync.js',
  'core_orders.js',
  'gas_store.js', 'gas_telegram.js', 'gas_gemini.js', 'gas_pdf.js', 'gas_import.js', 'gas_setup.js', 'gas_sync.js', 'gas_main.js'
];
const parts = FILES.map(f => {
  const src = fs.readFileSync(path.join(ROOT, 'apps-script', f), 'utf8');
  return `/* ======================================================================\n * ${f}\n * ====================================================================== */\n${src.trim()}\n`;
});
const header = `/*\n * POS bot for the family clothing shops: one-file build.\n * Generated by tools/bundle_gas.js on ${new Date().toISOString().slice(0, 10)}.\n * Paste this whole file into Code.gs in the Apps Script editor. Do not edit here;\n * edit the files in apps-script/ and run the bundler again.\n */\n\n`;
const out = header + parts.join('\n');
fs.mkdirSync(path.join(ROOT, 'apps-script', 'dist'), { recursive: true });
const outPath = path.join(ROOT, 'apps-script', 'dist', 'Code.gs');
fs.writeFileSync(outPath, out);
console.log('wrote ' + path.relative(ROOT, outPath) + ' (' + Math.round(out.length / 1024) + ' KB, ' + out.split('\n').length + ' lines)');

// clasp publishes apps-script/dist (apps-script/.clasp.json has "rootDir": "dist"), so the manifest goes
// next to Code.gs. The online project then holds exactly Code.gs and appsscript.json, as after a hand paste.
const manifestOut = path.join(ROOT, 'apps-script', 'dist', 'appsscript.json');
fs.copyFileSync(path.join(ROOT, 'apps-script', 'appsscript.json'), manifestOut);
console.log('wrote ' + path.relative(ROOT, manifestOut));
